public static List<List<Integer>> findSumPairs(int arr[], int sum) {
    List<List<Integer>> result = new ArrayList<>();
    Map<Integer, Integer> map = new HashMap<>();

    for (int i = 0; i < arr.length; i++) {
        int target = sum - arr[i];
        if (map.containsKey(target)) {
            result.add(Arrays.asList(map.get(target), i));
        }
        map.put(arr[i], i);
    }
    return result;
}

def find_longest_substring(string):
    """
    Finds the longest substring of unique characters in a given string.
    """
    longest_substring = ''
    current_substring = ''
    for ch in string:
        if ch not in current_substring:
            current_substring += ch
            if len(current_substring) > len(longest_substring):
                longest_substring = current_substring
        else:
            current_substring = ch
    return longest_substring

