        std::cout << i << " ";
    std::cout << "\n";

	return 0; 
}

def nth_fibonacci_number(n):
    """Find the value of n where n is the index of the Fibonacci Sequence.""" 
    if n < 2:
        return n 
    elif n == 2:
        return 1
    else:
        return nth_fibonacci_number(n-1) + nth_fibonacci_number(n-2)

